import React, { useContext } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { FaHome, FaBook, FaCalendarCheck, FaUserCircle, FaUsers } from 'react-icons/fa';
import { AuthContext } from '../../App';
import './BottomNav.css';

function BottomNav() {
  const { stateAuth } = useContext(AuthContext);
  const navigate = useNavigate();
  const location = useLocation();

  const user = stateAuth?.user || {};
  const typ = (user.typ || '').toUpperCase();

  const navItems = [];

  if (typ === 'STUDENT') {
    navItems.push(
      { label: 'Home', path: '/dashboard', icon: <FaHome /> },
      { label: 'Classes', path: '/classes', icon: <FaBook /> },
      { label: 'Homework', path: '/homework', icon: <FaBook /> },
      { label: 'Attendance', path: '/attendance', icon: <FaCalendarCheck /> },
      { label: 'Profile', path: '/profile', icon: <FaUserCircle /> }
    );
  } else if (typ === 'STAFF') {
    navItems.push(
      { label: 'Home', path: '/dashboard', icon: <FaHome /> },
      { label: 'Classes', path: '/classes', icon: <FaBook /> },
      { label: 'Students', path: '/students', icon: <FaUsers /> },
      { label: 'Attendance', path: '/attendance', icon: <FaCalendarCheck /> },
      { label: 'Profile', path: '/staff-profile', icon: <FaUserCircle /> }
    );
  }

  if (navItems.length === 0) return null;

  return (
    <div className="bottom-nav">
      {navItems.map((item, index) => (
        <button
          key={index}
          className={`bottom-nav-item ${location.pathname === item.path ? 'active' : ''}`}
          onClick={() => navigate(item.path)}
        >
          <div className="bottom-nav-icon">{item.icon}</div>
          <span className="bottom-nav-label">{item.label}</span>
        </button>
      ))}
    </div>
  );
}

export default BottomNav;
